/**
 * Compare an observed closing balance to the movements of its period
 *
 * `discrepancy = closing - (opening + sum of booked movements)`, with the period ending on the snapshot day. The opening figure is the latest active snapshot on or before the day preceding `periodStart` (a period of at most 366 days), and movements are summed from the day after that opening snapshot, so nothing booked between the two is dropped. The response `periodStart` is that effective first day. Pending rows of the same window are listed and counted but never summed. When a side is missing the discrepancy is null and `nonCalculableReason` says why; it is never zero by default.
 */
export const readAccountReconciliation = <ThrowOnError extends boolean = false>(options: Options<ReadAccountReconciliationData, ThrowOnError>): RequestResult<ReadAccountReconciliationResponses, ReadAccountReconciliationErrors, ThrowOnError> => (options.client ?? client).get<ReadAccountReconciliationResponses, ReadAccountReconciliationErrors, ThrowOnError>({
    security: [{
            in: 'cookie',
            name: 'cadran_session',
            type: 'apiKey'
        }],
    url: '/api/v1/accounts/{accountId}/reconciliation',
    ...options
});

/**
 * Reconcile an observed closing balance
 *
 * An account valued in `PORTFOLIO` mode refuses it with `422 portfolio_account_valued_by_portfolio`. `MATCH` requires a discrepancy of exactly zero (compared as decimals, so `1.10` equals `1.1`). `OVERRIDE` accepts a non-zero discrepancy as it stands and writes no transaction. `ADJUST` records one booked `ADJUSTMENT` movement equal to the discrepancy on the snapshot day, which is neither income nor expense, then reconciles. A non-calculable comparison refuses every resolution. The account is locked, so two concurrent requests never both adjust: the loser receives a 409.
 */
